// t440cg probe: where a cold capture's time goes, and what a commit-graph file changes.
use std::time::Instant;
use trunk_git::graph::{CommitMemo, capture_remembering};

fn ms(t: Instant) -> f64 { t.elapsed().as_secs_f64() * 1000.0 }

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let mode = std::env::args().nth(2).unwrap();
    if std::env::var_os("NOSTRICT").is_some() { git2::opts::strict_hash_verification(false); }
    let repo = git2::Repository::open(&path).unwrap();
    let t = Instant::now();
    let n = match mode.as_str() {
        "capture" => {
            let mut repo = repo;
            let s = capture_remembering(&mut repo, &CommitMemo::default()).unwrap();
            s.placement.oids.len()
        }
        "revwalk" => {
            let mut w = repo.revwalk().unwrap();
            w.set_sorting(git2::Sort::TOPOLOGICAL | git2::Sort::TIME).unwrap();
            w.push_glob("refs/*").unwrap();
            w.count()
        }
        "topology" => {
            // read every commit object, keep only parents and time
            let mut w = repo.revwalk().unwrap();
            w.push_glob("refs/*").unwrap();
            let mut n = 0;
            for oid in w { let c = repo.find_commit(oid.unwrap()).unwrap(); n += c.parent_count() + (c.time().seconds() as usize & 0); }
            n
        }
        "facts" => {
            let mut w = repo.revwalk().unwrap();
            w.push_glob("refs/*").unwrap();
            let mut n = 0;
            for oid in w { let c = repo.find_commit(oid.unwrap()).unwrap(); let a = c.author(); let s = c.summary().ok().flatten().unwrap_or("").to_owned(); let b = c.body().ok().flatten().map(str::to_owned); let an = a.name().unwrap_or("").to_owned(); let ae = a.email().unwrap_or("").to_owned(); n += s.len() + b.map_or(0, |b| b.len()) + an.len() + ae.len(); }
            n
        }
        "unsorted" => {
            let mut w = repo.revwalk().unwrap();
            w.push_glob("refs/*").unwrap();
            w.count()
        }
        "unsorted5" => {
            let mut n = 0;
            for _ in 0..5 { let repo = git2::Repository::open(&path).unwrap(); let mut w = repo.revwalk().unwrap(); w.push_glob("refs/*").unwrap(); n += w.count(); }
            n
        }
        "cgfile" => {
            let odb = repo.odb().unwrap();
            let p = std::path::Path::new(&path).join(".git/objects/info/commit-graph");
            usize::from(p.exists()) + usize::from(odb.exists(repo.head().unwrap().target().unwrap()))
        }
        _ => panic!("mode"),
    };
    println!("{mode}: {:.1} ms ({n})", ms(t));
}
